{
  "name": "@opencode-manager/memory",
  "version": "0.1.3",
  "type": "module",
  "oc-plugin": [
    "server",
    "tui"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./server": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "files": [
    "dist",
    "config.jsonc",
    "scripts",
    "README.md",
    "src/command/template"
  ],
  "bin": {
    "ocm-mem": "./dist/cli/index.js"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/chriswritescode-dev/opencode-memory.git"
  },
  "author": "Chris Scott",
  "description": "AI-powered memory management plugin for OpenCode - semantic search and persistent knowledge storage",
  "keywords": [
    "opencode",
    "memory",
    "semantic-search",
    "vector-embeddings",
    "ai-agent",
    "plugin"
  ],
  "license": "MIT",
  "homepage": "https://github.com/chriswritescode-dev/opencode-memory",
  "dependencies": {
    "@huggingface/transformers": "^3.8.1",
    "@opencode-ai/plugin": "^1.4.2",
    "@opencode-ai/sdk": "^1.4.2",
    "sqlite-vec": "0.1.7-alpha.2"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.1.92",
    "@opentui/solid": ">=0.1.92"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  },
  "optionalDependencies": {
    "sqlite-vec-darwin-arm64": "0.1.7-alpha.2",
    "sqlite-vec-darwin-x64": "0.1.7-alpha.2",
    "sqlite-vec-linux-arm64": "0.1.7-alpha.2",
    "sqlite-vec-linux-x64": "0.1.7-alpha.2",
    "sqlite-vec-windows-x64": "0.1.7-alpha.2"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "@opentui/core": "0.1.97",
    "@opentui/solid": "0.1.97",
    "@typescript-eslint/eslint-plugin": "^8.58.0",
    "@typescript-eslint/parser": "^8.58.0",
    "bun-types": "latest",
    "eslint": "^10.2.0",
    "eslint-config-prettier": "^10.1.8",
    "eslint-plugin-solid": "^0.14.5",
    "prettier": "^3.8.1",
    "solid-js": "^1.9.12",
    "typescript": "^5.7.3",
    "typescript-eslint": "^8.58.0"
  },
  "scripts": {
    "build": "bun scripts/build.ts",
    "lint": "eslint .",
    "postinstall": "node scripts/download-models.js",
    "prepublishOnly": "pnpm build",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "cli": "bun src/cli/index.ts"
  }
}
